package com.luminor.tavernquest.feature.onboarding.tavern
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.model.TavernEmblem;import com.luminor.tavernquest.domain.usecase.onboarding.CreateTavernUseCase;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class TavernCreationViewModel @Inject constructor(private val create:CreateTavernUseCase):ViewModel(){private val _ui=MutableStateFlow(TavernCreationUiState());val ui=_ui.asStateFlow();fun name(v:String){_ui.update{it.copy(name=v)}};fun emblem(v:TavernEmblem){_ui.update{it.copy(emblem=v)}};fun save(){val s=_ui.value;if(s.name.isBlank())return;viewModelScope.launch{_ui.update{it.copy(saving=true)};create(s.name,s.emblem);_ui.update{it.copy(saving=false,created=true)}}}}
